tool_input.command:
mkdir -p /tmp/gwsim && cd /tmp/gwsim && cat > sim.mjs <<'EOF'
import fs from "fs";
const src = fs.readFileSync(process.argv[2], "utf8");
const fn = src.slice(src.indexOf("export function gameStep"), src.indexOf("export const gameRuntime")).replace("export ", "");
const gameStep = new Function("IDLE", fn + "; return gameStep;")({ up: false, down: false, left: false, right: false });
const { carve } = await import(process.argv[3]);
let lvl = carve(7, 0, 45), s = { t: 0, depth: 0, miner: { x: -1, y: -1 }, start: [-1, -1], descended: false }, hostDepth = 0;
for (let k = 1; k <= 45; k++) {
  const T = k / 30, right = T >= 1 / 30 && T < 1 / 4;
  s = gameStep(s, { dt: 1 / 30, inputs: { start: [lvl.start.x, lvl.start.y], exit: [lvl.exit.x, lvl.exit.y] },
    controls: { pad: { up: false, down: false, left: false, right } },
    kernels: { control: (m, p) => { m.dx = p.right ? 1 : p.left ? -1 : 0; m.dy = 0; } } });
  console.log(k + "/30", JSON.stringify(s.miner), "depth", s.depth);
  if (k % 3 === 0 && s.depth !== hostDepth) { hostDepth = s.depth; lvl = carve(7, hostDepth, 45); console.log("  rebuild cave depth", hostDepth, lvl.start, lvl.exit); }
}
EOF
node sim.mjs /private/tmp/HKNInI-json-opus/game.package.js /private/tmp/HKNInI-json-opus/carve.js | head -16
